import java.util.List;

public class StreamOrderDemo {
    public static void main(String[] args) {
        List<String> items = List.of("alpha", "bravo", "charlie", "delta");

        System.out.println("--- forEach() on Parallel Stream (Unordered) ---");
        items.parallelStream().forEach(System.out::println);

        System.out.println("--- forEachOrdered() on Parallel Stream (Ordered) ---");
        items.parallelStream().forEachOrdered(System.out::println);
    }
}
